function testFrontMatter() {
  console.log(JSON.stringify(frontMatter("---\ncrop: Tomato\nnote: water at 6:00\n---\nPlanted six seedlings.")))
}

function frontMatter(text) {
  const lines = text.split("\n")
  const data = {}
  let dashesSeen = 0
  for (const line of lines) {
    if (line.trim() === "---") {
      dashesSeen++
    } else if (dashesSeen === 1) {
      const [key, ...rest] = line.split(":")
      data[key.trim()] = rest.join(":").trim()
    }
  }
  return data
}
